"""
You can define alarms by importing proper alarm definition from taf.rfrl.bts.alarms and updating it as needed
    1. Add imported dict to the list
    2. Add dictionary with desired params
        All available params:
        {
            'alarm_id': 1234,
            'fault_id': 5678,
            'fault_name': 'Some name',
            'hw_path':  'HW path',
            'severity':  'Minor',
            'reason':   'supplAlarmInfo'
        }
"""
import re
from taf.rfrl.utilities.robot.general import is_dry_run
from taf.rfrl.bts.alarms.classical_alarms_definition import CLASSICAL_FAULT_23, CLASSICAL_FAULT_4420, \
    CLASSICAL_FAULT_4478, CLASSICAL_FAULT_4589, CLASSICAL_FAULT_4592, CLASSICAL_FAULT_4654, CLASSICAL_FAULT_4655, \
    CLASSICAL_FAULT_4681, CLASSICAL_FAULT_6327, CLASSICAL_FAULT_7300, CLASSICAL_FAULT_7319, CLASSICAL_FAULT_8150, \
    CLASSICAL_FAULT_61524, CLASSICAL_FAULT_61648, CLASSICAL_FAULT_61649, CLASSICAL_FAULT_61652
from taf.rfrl.bts.alarms.asir_alarms_definition import ASIR_FAULT_61648

fault_4592_reason_pattern = re.compile('BTS booted at .* due to ((Software Reset)|(CommissioningChange)|(User)|'
                                       '(Reconfiguration)|(SwRollback)|(commissioning change)|(software rollback)|'
                                       '(software reset)|(user request)|(power on))')

CLASSICAL_FAULT_4592_CUSTOM_REASON = CLASSICAL_FAULT_4592 | {'severity': 'Warning',
                                                             'reason': fault_4592_reason_pattern}
CLASSICAL_FAULT_61649_PORT_443 = CLASSICAL_FAULT_61649 | {'fault_name': 'LMP access via port 443'}
CLASSICAL_FAULT_61649_PORT_3600 = CLASSICAL_FAULT_61649 | {'fault_name': 'LMP access via port 3600'}

_common_allowed_alarms = [
    CLASSICAL_FAULT_4592_CUSTOM_REASON,
    CLASSICAL_FAULT_4654,
    CLASSICAL_FAULT_4655,
    CLASSICAL_FAULT_4681,
    CLASSICAL_FAULT_8150,
    CLASSICAL_FAULT_61524,
    CLASSICAL_FAULT_61648,
    CLASSICAL_FAULT_61649_PORT_443,
    CLASSICAL_FAULT_61649_PORT_3600,
    CLASSICAL_FAULT_61652,
]

_common_asir_allowed_alarms = [
    int(ASIR_FAULT_61648['fault_id']),  # temporary, until asir_operations.py is not adapted
]

_allowed_alarms_during_tl_preparation = [
    CLASSICAL_FAULT_23,
    CLASSICAL_FAULT_4420,
    CLASSICAL_FAULT_4478,
    CLASSICAL_FAULT_4589,
    CLASSICAL_FAULT_6327,
    CLASSICAL_FAULT_7300,
    CLASSICAL_FAULT_7319,
]


def get_variables():
    if is_dry_run():
        return {}

    allowed_alarms = get_default_allowed_alarms()
    variables = {
        'allowed_alarms': allowed_alarms,
        'ALLOWED_ALARMS': allowed_alarms,
        'ALLOWED_ALARMS_DURING_TL_PREPARATION': _allowed_alarms_during_tl_preparation + allowed_alarms,
        'ASIR_ALLOWED_ALARMS': _common_asir_allowed_alarms
    }

    return variables


def get_default_allowed_alarms(bts_build_raw=None):
    allowed_alarms = []
    allowed_alarms.extend(_common_allowed_alarms)

    return allowed_alarms
